public async Task<string> FetchDataAsync(CancellationToken ct)
{
    // I/O-bound: thread is released while waiting for the network
    using var response = await _httpClient.GetAsync("/api/data", ct);
    response.EnsureSuccessStatusCode();
    return await response.Content.ReadAsStringAsync(ct);
}

public Task<int> ComputeHashAsync(string input)
{
    // CPU-bound: move work to the ThreadPool
    return Task.Run(() => ComputeSha256Hash(input));
}

private int ComputeSha256Hash(string input)
{
    using var sha = SHA256.Create();
    byte[] bytes = Encoding.UTF8.GetBytes(input);
    byte[] hash = sha.ComputeHash(bytes);
    return BitConverter.ToInt32(hash, 0);
}
